    13→export interface ImageSliderProps {
    14→  /** Array of images to display */
    15→  images: GalleryImage[];
    16→  /** Initial slide index */
    17→  initialIndex?: number;
    18→  /** Height of the slider */
    19→  height?: number | string;
    20→  /** Show navigation arrows */
    21→  showArrows?: boolean;
    22→  /** Show dot indicators */
    23→  showDots?: boolean;
    24→  /** Show thumbnail strip */
    25→  showThumbnails?: boolean;
    26→  /** Show image counter */
    27→  showCounter?: boolean;
    28→  /** Enable fullscreen mode on click */
    29→  enableFullscreen?: boolean;
    30→  /** Auto-play interval in ms (0 to disable) */
    31→  autoPlay?: number;
    32→  /** Custom class name */
    33→  className?: string;
    34→}
    35→
    36→/**
    37→ * ImageSlider component
    38→ *
    39→ * @example
    40→ * ```tsx
    41→ * <ImageSlider
    42→ *   images={[
    43→ *     { id: '1', src: '/img1.jpg', alt: 'Image 1' },
    44→ *     { id: '2', src: '/img2.jpg', alt: 'Image 2' },
    45→ *   ]}
    46→ *   showThumbnails
    47→ *   showArrows
    48→ *   showDots
    49→ * />
    50→ * ```
    51→ */
    52→export function ImageSlider({
    53→  images,
    54→  initialIndex = 0,
    55→  height = 500,
    56→  showArrows = true,
    57→  showDots = true,
    58→  showThumbnails = true,
    59→  showCounter = true,
    60→  enableFullscreen = true,
    61→  autoPlay = 0,
    62→  className,
    63→}: ImageSliderProps): React.ReactElement {
    64→  const [currentIndex, setCurrentIndex] = React.useState(initialIndex);
    65→  const [isFullscreen, setIsFullscreen] = React.useState(false);
    66→  const [isTransitioning, setIsTransitioning] = React.useState(false);
    67→  const [touchStart, setTouchStart] = React.useState<number | null>(null);
    68→  const [touchEnd, setTouchEnd] = React.useState<number | null>(null);
    69→  const sliderRef = React.useRef<HTMLDivElement>(null);
    70→
    71→  // Minimum swipe distance
    72→  const minSwipeDistance = 50;
    73→
    74→  const goToSlide = React.useCallback((index: number) => {
    75→    if (isTransitioning) return;
    76→    setIsTransitioning(true);
    77→    setCurrentIndex(index);
    78→    setTimeout(() => setIsTransitioning(false), 400);
    79→  }, [isTransitioning]);
    80→
    81→  const goToPrevious = React.useCallback(() => {
    82→    const newIndex = currentIndex === 0 ? images.length - 1 : currentIndex - 1;
    83→    goToSlide(newIndex);
    84→  }, [currentIndex, images.length, goToSlide]);
    85→
    86→  const goToNext = React.useCallback(() => {
    87→    const newIndex = currentIndex === images.length - 1 ? 0 : currentIndex + 1;
    88→    goToSlide(newIndex);
    89→  }, [currentIndex, images.length, goToSlide]);
    90→
    91→  // Auto-play
    92→  React.useEffect(() => {
    93→    if (autoPlay > 0 && !isFullscreen) {
    94→      const interval = setInterval(goToNext, autoPlay);
    95→      return () => clearInterval(interval);
    96→    }
    97→  }, [autoPlay, goToNext, isFullscreen]);
    98→
    99→  // Keyboard navigation
   100→  React.useEffect(() => {
   101→    const handleKeyDown = (e: KeyboardEvent) => {
   102→      if (e.key === 'ArrowLeft') {
   103→        goToPrevious();
   104→      } else if (e.key === 'ArrowRight') {
   105→        goToNext();
   106→      } else if (e.key === 'Escape' && isFullscreen) {
   107→        setIsFullscreen(false);
   108→      }
   109→    };
   110→
   111→    window.addEventListener('keydown', handleKeyDown);
   112→    return () => window.removeEventListener('keydown', handleKeyDown);
   113→  }, [goToPrevious, goToNext, isFullscreen]);
   114→
   115→  // Touch handlers
   116→  const onTouchStart = (e: React.TouchEvent) => {
   117→    setTouchEnd(null);
   118→    const touch = e.targetTouches[0];
   119→    if (touch) {
   120→      setTouchStart(touch.clientX);
   121→    }
   122→  };
   123→
   124→  const onTouchMove = (e: React.TouchEvent) => {
   125→    const touch = e.targetTouches[0];
   126→    if (touch) {
   127→      setTouchEnd(touch.clientX);
   128→    }
   129→  };
   130→
   131→  const onTouchEnd = () => {
   132→    if (!touchStart || !touchEnd) return;
   133→    const distance = touchStart - touchEnd;
   134→    const isLeftSwipe = distance > minSwipeDistance;
   135→    const isRightSwipe = distance < -minSwipeDistance;
   136→
   137→    if (isLeftSwipe) {
   138→      goToNext();
   139→    } else if (isRightSwipe) {
   140→      goToPrevious();
   141→    }
   142→  };
   143→
   144→  const handleImageClick = () => {
   145→    if (enableFullscreen) {
   146→      setIsFullscreen(true);
   147→    }
   148→  };
   149→
   150→  if (!images.length) {
   151→    return (
   152→      <div
   153→        className={cn('image-slider', className)}
   154→        style={{
   155→          height: typeof height === 'number' ? `${height}px` : height,
   156→          backgroundColor: 'var(--ds-color-neutral-surface-hover)',
   157→          borderRadius: 'var(--ds-border-radius-lg)',
   158→          display: 'flex',
   159→          alignItems: 'center',
   160→          justifyContent: 'center',
   161→        }}
   162→      >
   163→        <Paragraph data-size="sm" style={{ color: 'var(--ds-color-neutral-text-subtle)' }}>
   164→          Ingen bilder tilgjengelig
   165→        </Paragraph>
   166→      </div>
   167→    );
   168→  }
   169→
   170→  const sliderContent = (
   171→    <>
   172→      {/* Main slider */}
   173→      <div
   174→        ref={sliderRef}
   175→        className="image-slider-main"
   176→        style={{
   177→          position: 'relative',
   178→          height: typeof height === 'number' ? `${height}px` : height,
   179→          borderRadius: isFullscreen ? 0 : 'var(--ds-border-radius-lg)',
   180→          overflow: 'hidden',
   181→          cursor: enableFullscreen && !isFullscreen ? 'zoom-in' : 'default',
   182→        }}
   183→        onTouchStart={onTouchStart}
   184→        onTouchMove={onTouchMove}
   185→        onTouchEnd={onTouchEnd}
   186→        onClick={!isFullscreen ? handleImageClick : undefined}
   187→      >
   188→        {/* Slides container */}
   189→        <div
   190→          className="image-slider-track"
   191→          style={{
   192→            display: 'flex',
   193→            height: '100%',
   194→            transform: `translateX(-${currentIndex * 100}%)`,
   195→            transition: 'transform 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
   196→          }}
   197→        >
   198→          {images.map((image, index) => (
   199→            <div
   200→              key={image.id}
   201→              className="image-slider-slide"
   202→              style={{
   203→                minWidth: '100%',
   204→                height: '100%',
